    {
      "element_id": "prisma_2020_3_e1",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "Metabolic syndrome (MetS) is a major global public health problem associated with cardiovascular disease, type 2 diabetes mellitus (T2D), and increased mortality. Chronic psychological stress has been proposed as a contributor to metabolic dysfunction; however, evidence linking perceived stress to MetS and its individual components remains inconsistent.",
      "reason": "The Background describes current knowledge (MetS burden, proposed stress link) and the key uncertainty (inconsistent evidence)."
    },
    {
      "element_id": "prisma_2020_3_e2",
      "status": "PRESENT",
      "chunk_id": "text_3",
      "quote": "The Perceived Stress Scale (PSS) is a widely validated instrument for assessing subjective stress, yet its association with metabolic outcomes has not been systematically synthesised.",
      "reason": "The gap in systematic synthesis of PSS-metabolic outcome evidence establishes the need and importance of the review."
    },
    {
      "element_id": "prisma_2020_3_e3",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "No evidence of prior similar systematic reviews is reported; the rationale states the association 'has not been systematically synthesised', so no update/replication justification is required."
    },
    {
      "element_id": "prisma_2020_3_e4",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "This is a review of associations between perceived stress and metabolic parameters, not a review of intervention effects."
    },
    {
      "element_id": "prisma_2020_3_e5",
      "status": "NOT_APPLICABLE",
      "chunk_id": null,
      "quote": null,
      "reason": "The review examines associations, not complex interventions or delivery contexts, so a logic model is not required."
    }
  ],
  "confidence": 85
